— {{The number that moved.}}

void blit(u32 *fb, int fbw, const u32 *src,
          int w, int h, int dx, int dy) {
  for (int y = 0; y < h; y++) {
    u32 *row = fb + (dy + y) * fbw + dx;
    const u32 *s = src + y * w;
    for (int x = 0; x < w; x++)
      if (s[x] >> 24) row[x] = s[x];
  }
}
